import type { GuidanceDocument } from '../types/guidance';
import type { WorkerSelection } from '../types/change-request-types';
import type { DirectionRef } from '../types/direction-ref';
import type { FailureReasonCode } from '../utils/failureReason';
import {
  variantReferenceSchema,
  type VariantReference,
} from '../types/variant-reference';
import { z } from 'zod/v3';
import { ERROR_CODES, type ErrorCode } from './errors';
import { validateInspirationUrl } from './sourceContext';
import { RUN_LABEL_MAX_LENGTH, RUN_LABEL_MAX_WORDS } from './runLabel';
import type {
  VariantWorkItemInputByKind,
  VariantWorkItemKind,
} from './workItemInput';

export const STAGES = [
  'awaiting_briefs',
  'awaiting_approval',
  'work_items_ready',
  'waiting_for_results',
  'ready',
  'degraded',
  'failed',
  'cancelled',
] as const;

export type Stage = (typeof STAGES)[number];

export const TERMINAL_STAGES: ReadonlySet<Stage> = new Set([
  'ready',
  'degraded',
  'failed',
  'cancelled',
]);

export const WORK_ITEM_KINDS = [
  'brief',
  'scaffold_base',
  'static_preview',
  'refine_variant',
  'code_gen',
  'cleanup_runtime',
] as const;

export type WorkItemKind = (typeof WORK_ITEM_KINDS)[number];

export const WORK_ITEM_STATUSES = [
  'pending',
  'running',
  'succeeded',
  'failed',
  'cancelled',
] as const;

export type WorkItemStatus = (typeof WORK_ITEM_STATUSES)[number];

export interface LeaseRecord {
  leaseId: string;
  leaseOwner: string;
  leaseIssuedAt: number;
  leaseExpiresAt: number;
  attempt: number;
}

export interface StaticPreviewTargetElement {
  tagName?: string;
  className?: string;
  id?: string;
  textContent?: string;
  xpath?: string;
}

export interface WorkerRuntimeInfo {
  vendor: string;
  model: string;
  effort?: string;
}

interface WorkItemRecord {
  id: string;
  status: WorkItemStatus;
  attempt: number;
  dependsOn: string[];
  output?: unknown;
  error?: {
    code: ErrorCode | string;
    message: string;
    apiErrorStatus?: number;
  };
  lease?: LeaseRecord;
  runtime?: WorkerRuntimeInfo;
  acceptedReports: string[];
  internal?: boolean;
  removed?: boolean;
}

export type VariantWorkItem = {
  [Kind in VariantWorkItemKind]: WorkItemRecord & {
    kind: Kind;
    input: VariantWorkItemInputByKind[Kind];
  };
}[VariantWorkItemKind];

export interface PlanningWorkItem extends WorkItemRecord {
  kind: Exclude<WorkItemKind, VariantWorkItemKind>;
  input: unknown;
}

export type WorkItem = VariantWorkItem | PlanningWorkItem;

const DESIGN_CONTEXT_MARKDOWN_MAX_LENGTH = 50_000;
const DESIGN_CONTEXT_SLUG_MAX_LENGTH = 120;
const SOURCE_URL_MAX_LENGTH = 2_048;
const SOURCE_FINDING_MAX_LENGTH = 400;
const SOURCE_LIST_MAX_ITEMS = 24;
const USER_CONTEXT_LABEL_MAX_LENGTH = 80;
const USER_CONTEXT_TEXT_MAX_LENGTH = 50_000;
const USER_CONTEXT_PATH_MAX_LENGTH = 2_048;
const USER_CONTEXT_UPLOAD_DATA_URL_MAX_LENGTH = 70_000_000;
export const CONTEXT_ASSET_MAX_ITEMS = 12;

export const designContextEntrySchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('slug'),
    slug: z.string().min(1).max(DESIGN_CONTEXT_SLUG_MAX_LENGTH),
  }),
  z.object({
    kind: z.literal('markdown'),
    content: z.string().min(1).max(DESIGN_CONTEXT_MARKDOWN_MAX_LENGTH),
    label: z.string().min(1).max(60),
  }),
]);

export const sourceRoleSchema = z.enum([
  'primary',
  'inspiration',
  'competitor',
]);

export const rawUserContextInputSchema = z.discriminatedUnion('transport', [
  z.object({
    transport: z.literal('url'),
    url: z.string().min(1).max(SOURCE_URL_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    transport: z.literal('file_path'),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    mimeType: z.string().min(1).max(120).optional(),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    transport: z.literal('upload'),
    references: z.array(variantReferenceSchema).optional(),
    dataUrl: z.string().min(1).max(USER_CONTEXT_UPLOAD_DATA_URL_MAX_LENGTH),
    filename: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    transport: z.literal('directory_path'),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    transport: z.literal('text'),
    references: z.array(variantReferenceSchema).optional(),
    content: z.string().min(1).max(USER_CONTEXT_TEXT_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
]);

export const rawUserContextSourceSchema = z.discriminatedUnion('transport', [
  z.object({
    id: z.string().min(1),
    transport: z.literal('prompt'),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
  }),
  z.object({
    id: z.string().min(1),
    transport: z.literal('url'),
    url: z.string().min(1).max(SOURCE_URL_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    id: z.string().min(1),
    transport: z.literal('file'),
    origin: z.enum(['user', 'profile']).optional(),
    references: z.array(variantReferenceSchema).optional(),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    mimeType: z.string().min(1).max(120).optional(),
    originalFilename: z
      .string()
      .min(1)
      .max(USER_CONTEXT_LABEL_MAX_LENGTH)
      .optional(),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    id: z.string().min(1),
    transport: z.literal('directory'),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
  z.object({
    id: z.string().min(1),
    transport: z.literal('text'),
    origin: z.enum(['user', 'profile']).optional(),
    references: z.array(variantReferenceSchema).optional(),
    path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
    userIntent: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
  }),
]);

export const contextAssetInputSchema = z
  .object({
    path: z.string().trim().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
    label: z
      .string()
      .trim()
      .min(1)
      .max(USER_CONTEXT_LABEL_MAX_LENGTH)
      .optional(),
  })
  .strict();

export const stagedContextAssetSchema = z.object({
  id: z.string().min(1),
  path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
  originalFilename: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH),
  mimeType: z.string().min(1).max(120).optional(),
  sizeBytes: z.number().int().positive(),
  sha256: z.string().regex(/^[a-f0-9]{64}$/),
  label: z.string().min(1).max(USER_CONTEXT_LABEL_MAX_LENGTH).optional(),
});

export const storedUserContextSourceRecordSchema = z.object({
  source: rawUserContextSourceSchema,
  storage: z
    .object({
      sizeBytes: z.number().int().nonnegative().optional(),
      sha256: z.string().min(1).optional(),
      originalFilename: z.string().min(1).optional(),
    })
    .optional(),
});

export const rivetContextActionKindSchema = z.enum([
  'extract_design_system',
  'describe_motion',
]);

export const rivetContextActionSchema = z.object({
  id: z.string().min(1),
  kind: rivetContextActionKindSchema,
  sourceIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
  reason: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH),
  outputMetadataIds: z
    .array(z.string().min(1))
    .max(SOURCE_LIST_MAX_ITEMS)
    .optional(),
});

const rivetMetadataBaseSchema = z.object({
  id: z.string().min(1),
  sourceIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
  actionId: z.string().min(1).optional(),
  producedBy: z.enum(['rivet', 'agent', 'browser', 'skill']),
  path: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH).optional(),
  warnings: z
    .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
    .max(SOURCE_LIST_MAX_ITEMS)
    .optional(),
});

export const rivetMetadataSchema = z.discriminatedUnion('kind', [
  rivetMetadataBaseSchema.extend({
    kind: z.literal('design_system'),
    data: z.object({
      designMarkdown: z
        .string()
        .min(1)
        .max(DESIGN_CONTEXT_MARKDOWN_MAX_LENGTH)
        .optional(),
      evidenceStatus: z.enum(['captured', 'partial', 'inferred']).optional(),
      sourceFindings: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      sectionInventory: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      visualObservations: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      sourceRoles: z
        .array(
          z.object({
            sourceId: z.string().min(1),
            role: sourceRoleSchema,
            rationale: z
              .string()
              .min(1)
              .max(SOURCE_FINDING_MAX_LENGTH)
              .optional(),
          }),
        )
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      qualityBar: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      risks: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .max(SOURCE_LIST_MAX_ITEMS)
        .optional(),
    }),
  }),
  rivetMetadataBaseSchema.extend({
    kind: z.literal('motion_guidance'),
    data: z.object({
      motionMarkdown: z
        .string()
        .min(1)
        .max(DESIGN_CONTEXT_MARKDOWN_MAX_LENGTH)
        .optional(),
      notes: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .min(1)
        .max(SOURCE_LIST_MAX_ITEMS),
      timings: z
        .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
        .max(SOURCE_LIST_MAX_ITEMS)
        .optional(),
    }),
  }),
]);

export const variantContextBindingSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('global'),
    sourceIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
    actionIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
    metadataIds: z
      .array(z.string().min(1))
      .max(SOURCE_LIST_MAX_ITEMS)
      .optional(),
  }),
  z.object({
    kind: z.literal('slot'),
    slotIndex: z
      .number()
      .int()
      .nonnegative()
      .max(SOURCE_LIST_MAX_ITEMS - 1),
    sourceIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
    actionIds: z.array(z.string().min(1)).max(SOURCE_LIST_MAX_ITEMS),
    metadataIds: z
      .array(z.string().min(1))
      .max(SOURCE_LIST_MAX_ITEMS)
      .optional(),
  }),
]);

export const executionModeSchema = z.enum(['static_preview', 'vite_app']);
export const executionConfidenceSchema = z.enum(['low', 'medium', 'high']);

export const assetPlanEntrySchema = z.object({
  source: z.string().min(1).max(SOURCE_URL_MAX_LENGTH),
  destination: z.string().min(1).max(SOURCE_URL_MAX_LENGTH),
  referenceAs: z.string().min(1).max(SOURCE_URL_MAX_LENGTH),
});

export const executionCapabilityPlanSchema = z.object({
  mode: executionModeSchema,
  confidence: executionConfidenceSchema,
  reason: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH),
  assetPlan: z
    .array(assetPlanEntrySchema)
    .max(SOURCE_LIST_MAX_ITEMS)
    .optional(),
  runtimeRequirements: z
    .array(z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH))
    .max(SOURCE_LIST_MAX_ITEMS)
    .optional(),
  userQuestion: z.string().min(1).max(SOURCE_FINDING_MAX_LENGTH).optional(),
});

export type ExecutionMode = z.infer<typeof executionModeSchema>;
export type ExecutionConfidence = z.infer<typeof executionConfidenceSchema>;
export type AssetPlanEntry = z.infer<typeof assetPlanEntrySchema>;
export type ExecutionCapabilityPlan = z.infer<
  typeof executionCapabilityPlanSchema
>;

export const variantContextBundleSchema = z.object({
  version: z.literal(1),
  sessionId: z.string().min(1),
  contextBundlePath: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
  userContext: z.array(rawUserContextSourceSchema).min(1),
  rivetActions: z.array(rivetContextActionSchema).max(SOURCE_LIST_MAX_ITEMS),
  rivetMetadata: z.array(rivetMetadataSchema),
  contextAssets: z
    .array(stagedContextAssetSchema)
    .min(1)
    .max(CONTEXT_ASSET_MAX_ITEMS)
    .optional(),
  bindings: z.array(variantContextBindingSchema).optional(),
  executionPlan: executionCapabilityPlanSchema.optional(),
});

export const projectContextExisting = z.object({
  kind: z.literal('existing'),
  projectPath: z.string().min(1).optional(),
  designContext: z.array(designContextEntrySchema).optional(),
  variantContext: variantContextBundleSchema.optional(),
});

export const projectContextFresh = z.object({
  kind: z.literal('fresh'),
  workspacePath: z.string().min(1),
  workspaceRoot: z.string().min(1),
  framework: z.enum(['vite', 'next', 'astro', 'remix']).optional(),
  assetSourceRoot: z.string().min(1).max(SOURCE_URL_MAX_LENGTH).optional(),
  designContext: z.array(designContextEntrySchema).optional(),
  variantContext: variantContextBundleSchema.optional(),
  executionPlan: executionCapabilityPlanSchema.optional(),
});

export const projectContextSchema = z.discriminatedUnion('kind', [
  projectContextExisting,
  projectContextFresh,
]);

export type ProjectContext = z.infer<typeof projectContextSchema>;
export type DesignContextEntry = z.infer<typeof designContextEntrySchema>;
export type SourceRole = z.infer<typeof sourceRoleSchema>;
export type RawUserContextInput = z.infer<typeof rawUserContextInputSchema>;
export type RawUserContextSource = z.infer<typeof rawUserContextSourceSchema>;
export type ContextAssetInput = z.infer<typeof contextAssetInputSchema>;
export type StagedContextAsset = z.infer<typeof stagedContextAssetSchema>;
export type StoredUserContextSourceRecord = z.infer<
  typeof storedUserContextSourceRecordSchema
>;
export type RivetContextActionKind = z.infer<
  typeof rivetContextActionKindSchema
>;
export type RivetContextAction = z.infer<typeof rivetContextActionSchema>;
export type RivetMetadata = z.infer<typeof rivetMetadataSchema>;
export type VariantContextBinding = z.infer<typeof variantContextBindingSchema>;
export type VariantContextBundle = z.infer<typeof variantContextBundleSchema>;

