export interface HostVariantPlanningWorkItemSnapshot extends HostVariantWorkItemBase {
  kind: Exclude<WorkItemKind, 'static_preview' | 'refine_variant' | 'code_gen'>;
  input: unknown;
  outputSchema: unknown;
}

export type HostVariantWorkItemSnapshot =
  | HostVariantImplementationWorkItemSnapshot
  | HostVariantPlanningWorkItemSnapshot;

export type VariantQaStatus = 'passed' | 'failed' | 'not_run';

export type VariantQaIssueKind =
  | 'asset_load_failed'
  | 'console_error'
  | 'preview_unavailable'
  | 'output_integrity'
  | 'verification_unavailable';

export interface VariantQaIssue {
  kind: VariantQaIssueKind;
  detail: string;
  message?: string;
}

export interface VariantQaResult {
  status: VariantQaStatus;
  issues: VariantQaIssue[];
  summary: string;
  checkedSource?: string;
}

export const targetSchema = z.object({
  type: z.enum(['element', 'file', 'route']),
  ref: z.string().min(1),
});

export type Target = z.infer<typeof targetSchema>;

export const briefSchema = z.object({
  briefId: z.string().min(1),
  label: z
    .string()
    .min(1)
    .max(48)
    .describe(
      'A concise title in the user\'s preferred display language that names what THIS direction actually changes, so the user instantly understands its intent. Describe the change, not the vibe — no marketing language or evocative adjectives. A standalone title only, never a "Title — descriptor" compound: no em dashes, en dashes, or colons — put any descriptor in the body instead. Rendered as the variant card title in the UI.',
    ),
  body: z
    .string()
    .min(1)
    .max(600)
    .describe(
      "One or two concise sentences in the user's preferred display language describing the variant direction and the scope it must respect. Name the main difference from the other variants. When the request targets a specific element/file/route, scope this direction to that element and its immediate section — do not restyle or re-describe the rest of the page. Otherwise (a whole-page or from-scratch request) keep the original user deliverable intact (for example, a complete landing page still needs hero, product/value props, proof, CTA, and footer unless the user asked for less). No bullets, no line breaks, no abbreviations, no value codes.",
    ),
  notes: z
    .string()
    .trim()
    .min(1)
    .max(4000)
    .optional()
    .describe(
      "Optional implementation notes for this direction, delivered verbatim to its worker's briefing (design tokens, motion specs, constraints). Never rendered in UI chips.",
    ),
  visualReferenceUrl: z
    .string()
    .url()
    .refine((url) => validateInspirationUrl(url).ok, {
      message:
        'visualReferenceUrl must be an HTTP(S) URL that does not target local or private networks',
    })
    .optional()
    .describe(
      'Optional HTTP(S) inspiration URL. Subject to SSRF guard — must not resolve to local or private network targets.',
    ),
});

export type Brief = z.infer<typeof briefSchema>;

export const variantWorkItemContextSchema = z.object({
  references: z.array(variantReferenceSchema).optional(),
  contextBundlePath: z.string().min(1).max(USER_CONTEXT_PATH_MAX_LENGTH),
  userContext: z.array(rawUserContextSourceSchema),
  rivetMetadata: z.array(rivetMetadataSchema),
  contextAssets: z
    .array(stagedContextAssetSchema)
    .min(1)
    .max(CONTEXT_ASSET_MAX_ITEMS)
    .optional(),
  brief: briefSchema,
  executionMode: executionModeSchema.optional(),
});

export type VariantWorkItemContext = z.infer<
  typeof variantWorkItemContextSchema
>;

export const VARIANT_COUNT_MIN = 1;
export const VARIANT_COUNT_MAX = 12;

export const DEFAULT_VARIANT_COUNT: number = (() => {
  const envVal = process.env.RIVET_DEFAULT_VARIANT_COUNT;
  if (!envVal) return 3;
  const parsed = parseInt(envVal, 10);
  if (isNaN(parsed)) return 3;
  return Math.max(VARIANT_COUNT_MIN, Math.min(VARIANT_COUNT_MAX, parsed));
})();

export const runLabelSchema = z
  .string()
  .trim()
  .min(1)
  .max(RUN_LABEL_MAX_LENGTH)
  .refine((label) => label.split(/\s+/).length <= RUN_LABEL_MAX_WORDS, {
    message: `Run labels must contain at most ${RUN_LABEL_MAX_WORDS} words`,
  })
  .optional()
  .describe(
    "A concise label in the user's preferred display language for the INTENT of THIS run — the change the prompt asks for, shared by every variant (NOT a per-variant name). Name the change, not the vibe; no marketing or evocative adjectives. Shown on every variant row. Omit it only for human-direct starts — Rivet then derives one heuristically.",
  );

export const startVariantsBriefContent = briefSchema.omit({ briefId: true });

export type StartVariantsBriefContent = z.infer<
  typeof startVariantsBriefContent
>;

export interface LeasedWorkItemDescriptor {
  id: string;
  kind: WorkItemKind;
  attempt: number;
  dependsOn: string[];
  input: unknown;
  output_schema: unknown;
}

export interface TerminalSummary {
  successCount: number;
  failureCount: number;
  cancelledCount: number;
  variants: Array<{
    workItemId: string;
    status: WorkItemStatus;
    label?: string;
  }>;
}

